#include <stdio.h>

int main() {
    int a = 10;
    char c = 'A';
    double d = 3.14;

    int *pi = &a;
    char *pc = &c;
    double *pd = &d;

    printf("int* 크기: %lu\n", sizeof(pi));
    printf("char* 크기: %lu\n", sizeof(pc));
    printf("double* 크기: %lu\n", sizeof(pd));

    return 0;
}
